import FeatureSectionV1 from "./feature-section-v1"

export default function Page() {
  return <FeatureSectionV1 />
}

"use client"

import { useFeatureAnimation } from "../hooks/use-feature-animation"
import { features } from "../lib/features"
import FeatureCard from "./feature-card"

export default function FeatureGrid() {
  const { ref, isVisible } = useFeatureAnimation()

  return (
    <div
      ref={ref}
      className="grid grid-cols-1 gap-4 sm:gap-5 lg:grid-cols-3 lg:grid-rows-2"
    >
      {features.map((feature, i) => (
        <FeatureCard
          key={feature.id}
          feature={feature}
          index={i}
          isVisible={isVisible}
        />
      ))}
    </div>
  )
}

import Image from "next/image"

import { cn } from "@/lib/utils"
import type { Feature } from "../lib/features"

type Props = {
  feature: Feature
  index: number
  isVisible: boolean
}

export default function FeatureCard({ feature, index, isVisible }: Props) {
  const Icon = feature.icon
  const isWide = feature.layout === "wide"

  return (
    <article
      className={cn(
        "fsv1-card group relative overflow-hidden rounded-2xl border bg-card shadow-sm",
        isWide ? "lg:col-span-2" : "lg:col-span-1",
      )}
      data-visible={isVisible}
      data-layout={feature.layout}
      style={{ transitionDelay: `${index * 80}ms` }}
    >
      {isWide && feature.imageSrc ? (
        <div className="flex h-full min-h-0 flex-col gap-5 p-5 lg:flex-row lg:items-stretch">
          <div className="relative aspect-4/3 w-full shrink-0 overflow-hidden rounded-xl lg:aspect-auto lg:w-1/2 lg:min-h-[220px]">
            <Image
              src={feature.imageSrc}
              alt=""
              fill
              className="object-cover object-center"
              sizes="(max-width: 1024px) 100vw, 50vw"
              priority={index === 0}
            />
          </div>
          <div className="flex flex-col justify-center gap-3 lg:w-1/2 lg:py-1">
            <div className="fsv1-icon-wrap flex h-10 w-10 shrink-0 items-center justify-center rounded-xl">
              <Icon className="fsv1-icon size-[18px]" strokeWidth={1.75} />
            </div>
            <div className="flex flex-col gap-1.5">
              <h3 className="text-base font-semibold tracking-tight">
                {feature.title}
              </h3>
              <p className="text-sm leading-relaxed text-muted-foreground">
                {feature.description}
              </p>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex h-full flex-col gap-4 p-6">
          <div className="fsv1-icon-wrap flex h-10 w-10 shrink-0 items-center justify-center rounded-xl">
            <Icon className="fsv1-icon size-[18px]" strokeWidth={1.75} />
          </div>
          <div className="flex flex-col gap-1.5">
            <h3 className="text-base font-semibold tracking-tight">
              {feature.title}
            </h3>
            <p className="text-sm leading-relaxed text-muted-foreground">
              {feature.description}
            </p>
          </div>
        </div>
      )}
    </article>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

export function useFeatureAnimation() {
  const ref = useRef<HTMLDivElement>(null)
  const [isVisible, setIsVisible] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      { threshold: 0.1 },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  return { ref, isVisible }
}

/* feature-section-v1 — all classes scoped with fsv1- prefix */

/* ─── Card entrance ──────────────────────────────────────────── */

.fsv1-card {
  opacity: 0;
  transform: translateY(20px);
  transition-property: opacity, transform, box-shadow;
  transition-duration: 0.55s;
  transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

.fsv1-card[data-visible="true"] {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Card hover lift ────────────────────────────────────────── */

.fsv1-card:hover {
  box-shadow:
    0 2px 8px -2px rgb(0 0 0 / 0.06),
    0 8px 24px -6px rgb(0 0 0 / 0.08);
}

.dark .fsv1-card:hover {
  box-shadow:
    0 2px 8px -2px rgb(0 0 0 / 0.3),
    0 8px 24px -6px rgb(0 0 0 / 0.4);
}

/* ─── Icon tile (dark glass, light glyph) ────────────────────── */

.fsv1-icon-wrap {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid rgb(255 255 255 / 0.22);
  background: linear-gradient(
    165deg,
    rgb(30 41 59 / 0.78) 0%,
    rgb(15 23 42 / 0.55) 45%,
    rgb(15 23 42 / 0.42) 100%
  );
  backdrop-filter: blur(12px) saturate(1.4);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  box-shadow:
    0 1px 0 rgb(255 255 255 / 0.22) inset,
    0 -1px 0 rgb(0 0 0 / 0.28) inset,
    0 1px 2px rgb(0 0 0 / 0.1),
    0 4px 10px -2px rgb(0 0 0 / 0.16),
    0 10px 24px -8px rgb(0 0 0 / 0.14);
}

.fsv1-icon {
  color: hsl(0 0% 98%);
  filter: drop-shadow(0 1px 1px rgb(0 0 0 / 0.25));
}

.dark .fsv1-icon-wrap {
  border-color: rgb(255 255 255 / 0.16);
  background: linear-gradient(
    165deg,
    rgb(255 255 255 / 0.14) 0%,
    rgb(255 255 255 / 0.06) 40%,
    rgb(15 23 42 / 0.65) 100%
  );
  box-shadow:
    0 1px 0 rgb(255 255 255 / 0.14) inset,
    0 -1px 0 rgb(0 0 0 / 0.55) inset,
    0 2px 4px rgb(0 0 0 / 0.35),
    0 10px 22px -6px rgb(0 0 0 / 0.5);
}

.dark .fsv1-icon {
  filter: drop-shadow(0 1px 2px rgb(0 0 0 / 0.45));
}

/* ─── Reduced motion ─────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .fsv1-card {
    opacity: 1;
    transform: none;
    transition: box-shadow 0.2s ease;
  }

  .fsv1-card[data-visible="true"] {
    transform: none;
  }
}
